import os, json, glob, time

def latest(path):
    files = []
    if os.path.isdir(path):
        for fp in glob.glob(os.path.join(path, "*.json")):
            try:
                mt = os.path.getmtime(fp)
            except Exception:
                mt = 0.0
            files.append((mt, fp))
    if not files:
        return None
    files.sort()
    return files[-1][1]

def load(p):
    with open(p, "r", encoding="utf-8") as f:
        return json.load(f)

def summary(m, path):
    return {
        "path": path,
        "lineage": m.get("lineage"),
        "root": m.get("root"),
        "file_count": m.get("file_count"),
        "total_bytes": m.get("total_bytes"),
        "versions_detected": sorted(set(m.get("versions_detected") or [])),
        "manifest_hash": m.get("manifest_hash"),
    }

def main():
    a_path = latest("storage/shared/quantum_probe/manifests_v2/kairos")
    b_path = None
    for sub in ["volition", "volition_iv"]:
        cand = os.path.join("storage/shared/quantum_probe/manifests_v2", sub)
        p = latest(cand)
        if p:
            b_path = p
            break

    if not a_path or not b_path:
        print("V2_DIFF_RESULT NO_MANIFESTS", a_path, b_path)
        return

    A = load(a_path); B = load(b_path)
    SA = summary(A, a_path); SB = summary(B, b_path)

    res = {
        "a": SA,
        "b": SB,
        "hash_equal": (SA["manifest_hash"] == SB["manifest_hash"]),
        "file_count_diff": (SB["file_count"] or 0) - (SA["file_count"] or 0),
        "bytes_diff": (SB["total_bytes"] or 0) - (SA["total_bytes"] or 0),
        "versions_diff": {
            "only_in_a": sorted(set(SA["versions_detected"]) - set(SB["versions_detected"])),
            "only_in_b": sorted(set(SB["versions_detected"]) - set(SA["versions_detected"])),
        }
    }
    print("V2_DIFF_SUMMARY", json.dumps(res, ensure_ascii=False))
    print("V2_DIFF_RESULT", "MATCH" if res["hash_equal"] else "DIVERGENCE")

if __name__ == "__main__":
    main()
